/**
 * Skill taxonomy for the salary engine.
 * `driver` (-10..+25) is how strongly the skill moves pay once present on a profile;
 * `demand` (0-100) is current market demand; `trend` is the YoY change in posting share (%).
 * Aliases are lowercase; the catalog builds a lookup over name + aliases.
 */
import type { SkillDef } from "./types";

type Cat = SkillDef["category"];

function s(name: string, category: Cat, aliases: string[], driver: number, demand: number, trend: number): SkillDef {
  return { name, category, aliases, driver, demand, trend };
}

